import os
import requests
from openai import OpenAI
import json

client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))

# Tavily search tool implementation
def web_search(query: str) -> str:
    """Execute web search via Tavily API and return formatted results."""
    response = requests.post(
        "https://api.tavily.com/search",
        json={
            "api_key": os.getenv('TAVILY_API_KEY'),
            "query": query,
            "search_depth": "advanced",
            "max_results": 5
        },
        timeout=10
    )

    if response.status_code != 200:
        return "Search failed. Please try again or rephrase your query."

    results = response.json().get('results', [])
    formatted = "\n\n".join([
        f"**{r['title']}** ({r['url']})\n{r['snippet']}"
        for r in results[:3]
    ])
    return formatted if formatted else "No relevant results found."

# Tool schema for LLM
tools = [{
    "type": "function",
    "function": {
        "name": "web_search",
        "description": "Search the web for current information when the query requires recent data (after April 2023), financial figures, regulatory updates, or fact verification for high-stakes decisions.",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Search query"}
            },
            "required": ["query"]
        }
    }
}]

def run_agent(user_message: str):
    messages = [
        {"role": "system", "content": "You are a research assistant. Use web search for recent or high-stakes information. Always cite sources."},
        {"role": "user", "content": user_message}
    ]

    response = client.chat.completions.create(
        model="gpt-4-turbo",
        messages=messages,
        tools=tools,
        tool_choice="auto"
    )

    # Handle tool call
    if response.choices[0].message.tool_calls:
        tool_call = response.choices[0].message.tool_calls[0]
        args = json.loads(tool_call.function.arguments)
        result = web_search(args['query'])

        # Inject search results and re-invoke
        messages.append(response.choices[0].message)
        messages.append({"role": "tool", "tool_call_id": tool_call.id, "content": result})

        final_response = client.chat.completions.create(
            model="gpt-4-turbo",
            messages=messages
        )
        return final_response.choices[0].message.content

    return response.choices[0].message.content

# Usage
print(run_agent("What was Microsoft's revenue in Q4 2024?"))

