# Cost tracking and model cascading logic
import openai
from datetime import datetime

COST_PER_1M_TOKENS = {
    "gpt-3.5-turbo": {"input": 0.50, "output": 1.50},
    "gpt-4o-mini": {"input": 0.15, "output": 0.60},
    "gpt-4": {"input": 15.0, "output": 30.0}
}

def route_by_complexity(query: str, metadata: dict):
    """Route to cost-appropriate model based on query complexity"""
    word_count = len(query.split())
    has_reasoning_keywords = any(kw in query.lower() 
        for kw in ["analyze", "compare", "explain why", "recommend"])

    if word_count < 20 and not has_reasoning_keywords:
        model = "gpt-3.5-turbo"
    elif word_count < 100 and not has_reasoning_keywords:
        model = "gpt-4o-mini"
    else:
        model = "gpt-4"

    response = openai.chat.completions.create(
        model=model, messages=[{"role": "user", "content": query}]
    )

    # Track cost with attribution
    input_cost = (response.usage.prompt_tokens / 1_000_000) * \
                 COST_PER_1M_TOKENS[model]["input"]
    output_cost = (response.usage.completion_tokens / 1_000_000) * \
                  COST_PER_1M_TOKENS[model]["output"]

    log_cost({
        "timestamp": datetime.utcnow(),
        "team": metadata["team"],
        "feature": metadata["feature"],
        "customer_id": metadata["customer_id"],
        "model": model,
        "cost_usd": input_cost + output_cost
    })

    return response.choices[0].message.content

