# Python example: allowlist enforcement in orchestration layer
from typing import Dict, List, Set
from dataclasses import dataclass

@dataclass
class AgentConfig:
    agent_id: str
    tool_allowlist: Set[str]
    description: str

class ToolOrchestrator:
    def __init__(self):
        self.agents: Dict[str, AgentConfig] = {}
        self.violation_log = []

    def register_agent(self, config: AgentConfig):
        self.agents[config.agent_id] = config

    def invoke_tool(self, agent_id: str, tool_name: str, **kwargs):
        """Enforce allowlist before tool execution."""
        if agent_id not in self.agents:
            raise ValueError(f"Unknown agent: {agent_id}")

        agent = self.agents[agent_id]

        if tool_name not in agent.tool_allowlist:
            violation = f"DENIED: Agent '{agent_id}' attempted '{tool_name}'"
            self.violation_log.append(violation)
            raise PermissionError(
                f"Tool '{tool_name}' not in allowlist for agent '{agent_id}'"
            )

        # Execute tool (placeholder)
        print(f"Executing {tool_name} for {agent_id}")
        return {"status": "success"}

# Setup
