# Golden set validation in CI/CD
import asyncio
from typing import List, Dict
import json

class GoldenSetEvaluator:
    def __init__(self, agent_system, golden_set_path: str):
        self.system = agent_system
        with open(golden_set_path) as f:
            self.golden_cases = json.load(f)

    async def evaluate(self) -> Dict:
        results = []
        for case in self.golden_cases:
            output = await self.system.process(case['input'])
            correct = self._compare(output, case['expected'])
            results.append({
                'case_id': case['id'],
                'correct': correct,
                'output': output,
                'category': case['category']
            })

        accuracy = sum(r['correct'] for r in results) / len(results)
        by_category = self._breakdown_by_category(results)

        return {
            'overall_accuracy': accuracy,
            'by_category': by_category,
            'failures': [r for r in results if not r['correct']]
        }

    def _compare(self, actual, expected) -> bool:
        # Semantic comparison for agent outputs
        # In production: use LLM-as-judge or structured field matching
        return actual.get('decision') == expected.get('decision')

    def _breakdown_by_category(self, results: List[Dict]) -> Dict:
        categories = {}
        for r in results:
            cat = r['category']
            if cat not in categories:
                categories[cat] = {'total': 0, 'correct': 0}
            categories[cat]['total'] += 1
            categories[cat]['correct'] += int(r['correct'])
        return {k: v['correct']/v['total'] for k, v in categories.items()}

# In CI/CD pipeline
async def quality_gate():
    evaluator = GoldenSetEvaluator(production_system, 'golden_set.json')
    metrics = await evaluator.evaluate()

    if metrics['overall_accuracy'] < 0.95:
        print(f"BLOCKED: Accuracy {metrics['overall_accuracy']:.2%} below 95% threshold")
        print(f"Failures: {len(metrics['failures'])}")
        exit(1)

    print(f"✓ Golden set passed: {metrics['overall_accuracy']:.2%}")

