# A/B testing framework for agent configurations
import hashlib
import random
from dataclasses import dataclass
from typing import Dict, Literal
import asyncio

@dataclass
class ExperimentConfig:
    name: str
    traffic_percentage: float  # 0.0 to 1.0
    agent_config: Dict

class ABTestRouter:
    def __init__(self):
        self.experiments = {
            'control': ExperimentConfig(
                name='control',
                traffic_percentage=0.90,
                agent_config={'model': 'gpt-4', 'orchestration': 'sequential'}
            ),
            'challenger': ExperimentConfig(
                name='challenger',
                traffic_percentage=0.10,
                agent_config={'model': 'claude-3-5-sonnet', 'orchestration': 'parallel'}
            )
        }
        self.metrics = {'control': [], 'challenger': []}

    def assign_variant(self, user_id: str) -> str:
        # Consistent hashing: same user always gets same variant
        hash_val = int(hashlib.sha256(user_id.encode()).hexdigest(), 16)
        threshold = hash_val % 100

        if threshold < self.experiments['challenger'].traffic_percentage * 100:
            return 'challenger'
        return 'control'

    async def route_request(self, user_id: str, request: Dict) -> Dict:
        variant = self.assign_variant(user_id)
        config = self.experiments[variant]

        # Execute with assigned configuration
        start = asyncio.get_event_loop().time()
        result = await self._execute_agent_system(request, config.agent_config)
        latency = asyncio.get_event_loop().time() - start

        # Track metrics
        self.metrics[variant].append({
            'request_id': request['id'],
            'latency_ms': latency * 1000,
            'cost': result['token_count'] * 0.00003,  # Example: $0.03/1K tokens
            'quality_score': result.get('quality_score'),
            'error': result.get('error') is not None
        })

        # Tag result with variant for downstream analysis
        result['experiment_variant'] = variant
        return result

    async def _execute_agent_system(self, request: Dict, config: Dict) -> Dict:
        # Initialize agents with config
        if config['orchestration'] == 'parallel':
            return await self._parallel_execution(request, config)
        return await self._sequential_execution(request, config)

    def analyze_results(self) -> Dict:
        """Run after experiment concludes"""
        control_metrics = self.metrics['control']
        challenger_metrics = self.metrics['challenger']

        return {
            'sample_size': {
                'control': len(control_metrics),
                'challenger': len(challenger_metrics)
            },
            'latency_p50': {
                'control': self._percentile([m['latency_ms'] for m in control_metrics], 50),
                'challenger': self._percentile([m['latency_ms'] for m in challenger_metrics], 50)
            },
            'cost_per_request': {
                'control': sum(m['cost'] for m in control_metrics) / len(control_metrics),
                'challenger': sum(m['cost'] for m in challenger_metrics) / len(challenger_metrics)
            },
            'error_rate': {
                'control': sum(m['error'] for m in control_metrics) / len(control_metrics),
                'challenger': sum(m['error'] for m in challenger_metrics) / len(challenger_metrics)
            }
        }

# Usage in production
router = ABTestRouter()

