# Regression gate implementation for healthcare AI agent
import json
from typing import Dict, List
import numpy as np

class RegressionGate:
    def __init__(self, baseline_metrics: Dict[str, float], 
                 quality_threshold: float = 0.05,
                 cost_threshold: float = 0.20):
        """
        Args:
            baseline_metrics: {'f1': 0.94, 'cost_per_tx': 0.18}
            quality_threshold: Max acceptable quality degradation (0.05 = 5%)
            cost_threshold: Max acceptable cost increase (0.20 = 20%)
        """
        self.baseline = baseline_metrics
        self.quality_threshold = quality_threshold
        self.cost_threshold = cost_threshold

    def evaluate(self, candidate_metrics: Dict[str, float], 
                 stratified_metrics: Dict[str, Dict[str, float]] = None) -> Dict:
        """
        Evaluate candidate model against regression thresholds.

        Returns:
            {'passed': bool, 'violations': List[str], 'rollback': bool}
        """
        violations = []

        # Quality regression check
        quality_metrics = ['f1', 'auroc', 'sensitivity', 'specificity']
        for metric in quality_metrics:
            if metric in self.baseline and metric in candidate_metrics:
                degradation = (self.baseline[metric] - candidate_metrics[metric]) / self.baseline[metric]
                if degradation > self.quality_threshold:
                    violations.append(
                        f"{metric} degraded {degradation:.1%} (threshold: {self.quality_threshold:.1%})"
                    )

        # Cost regression check
        if 'cost_per_tx' in self.baseline and 'cost_per_tx' in candidate_metrics:
            cost_increase = (candidate_metrics['cost_per_tx'] - self.baseline['cost_per_tx']) / self.baseline['cost_per_tx']
            if cost_increase > self.cost_threshold:
                violations.append(
                    f"Cost increased {cost_increase:.1%} (threshold: {self.cost_threshold:.1%})"
                )

        # Stratified subgroup analysis
        if stratified_metrics:
            for subgroup, metrics in stratified_metrics.items():
                for metric, value in metrics.items():
                    if metric in self.baseline:
                        subgroup_degradation = (self.baseline[metric] - value) / self.baseline[metric]
                        if subgroup_degradation > self.quality_threshold:
                            violations.append(
                                f"{subgroup} {metric} degraded {subgroup_degradation:.1%}"
                            )

        return {
            'passed': len(violations) == 0,
            'violations': violations,
            'rollback': len(violations) > 0,
            'candidate_metrics': candidate_metrics
        }

# Example usage in CI pipeline
if __name__ == "__main__":
    # Baseline from previous production model
    baseline = {
        'f1': 0.94,
        'auroc': 0.96,
        'cost_per_tx': 0.18
    }

    # New candidate model metrics
    candidate = {
        'f1': 0.88,  # 6.4% degradation - FAILS gate
        'auroc': 0.95,
        'cost_per_tx': 0.16
    }

    # Stratified metrics by language
    stratified = {
        'spanish_language': {'f1': 0.71, 'auroc': 0.82},
        'english_language': {'f1': 0.92, 'auroc': 0.96}
    }

    gate = RegressionGate(baseline)
    result = gate.evaluate(candidate, stratified)

    print(json.dumps(result, indent=2))

    if not result['passed']:
        print("\n❌ DEPLOYMENT BLOCKED")
        print("Violations:", result['violations'])
        # Trigger rollback automation
    else:
        print("\n✅ CLEARED FOR DEPLOYMENT")
